I'll help you implement and optimize the CUDA kernel for matrix multiplication. Let's start with iteration 1.

### Iteration 1: Basic Matrix Multiplication Kernel
We'll implement a naive matrix multiplication kernel with coalesced memory access. Each thread computes one output element by iterating through the corresponding row and column.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(
    const float* __restrict__ a,
    const float* __restrict__ b,
    float* __restrict__ out,
    int n
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < n && col < n) {
        float sum = 0.0f;
        for (int k = 0; k < n; k++) {
            sum += a[row * n + k] * b[k * n + col];
        }
        out[row * n + col] = sum;
    }
}

torch::Tensor matmul_forward_cuda(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.size(0) == a.size(1), "Matrix must be square");
    TORCH_CHECK(a.size(0) == b.size(0), "Matrix dimensions must match");
    int n = a.size(0);
    auto out = torch::zeros({n, n}, a.options());

    dim3 threads(16, 16);
    dim3 blocks((n + threads.x - 1) / threads.x, (n + threads.y - 1) / threads.y);

    matmul_kernel<<<blocks, threads>>>(
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        n
    );

    return out;
}
"""

cpp_source = "torch::Tensor matmul_forward_cuda(torch::Tensor a, torch::Tensor b);"

matmul_extension = load_inline(
    name='matmul_extension',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['matmul_forward_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, a, b):
        return matmul_extension.matmul_forward_cuda(a, b)
